<?php
require_once 'config.php';$uid=require_user();
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();$action=$_POST['action']??'';
 if($action==='remove'){$id=(int)($_POST['cart_id']??0);$q=$conn->prepare('DELETE FROM cart WHERE id=? AND user_id=?');$q->bind_param('ii',$id,$uid);$q->execute();flash('success','Позицію видалено.');}
 elseif($action==='clear'){$q=$conn->prepare('DELETE FROM cart WHERE user_id=?');$q->bind_param('i',$uid);$q->execute();flash('success','Кошик очищено.');}
 elseif($action==='update'){$id=(int)($_POST['cart_id']??0);$qty=(int)($_POST['quantity']??1);if($qty<1||$qty>50)flash('error','Кількість має бути від 1 до 50.');else{$q=$conn->prepare('UPDATE cart SET quantity=? WHERE id=? AND user_id=?');$q->bind_param('iii',$qty,$id,$uid);$q->execute();flash('success','Кількість оновлено.');}}
 redirect_to('cart.php');
}
$q=$conn->prepare('SELECT c.*, p.product_type AS product_type FROM cart c LEFT JOIN products p ON p.id=c.pid WHERE c.user_id=? ORDER BY c.id DESC');$q->bind_param('i',$uid);$q->execute();$items=$q->get_result()->fetch_all(MYSQLI_ASSOC);$sum=0;foreach($items as $r)$sum+=(float)$r['price']*(int)$r['quantity'];
?>
<!doctype html><html lang="uk"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Кошик — flora.atelier</title><link rel="stylesheet" href="css/style.css"><link rel="stylesheet" href="css/flor-v5.css"><link rel="stylesheet" href="css/flor-v6.css"><link rel="stylesheet" href="css/flor-v7.css"><link rel="stylesheet" href="css/flor-v8.css"><link rel="stylesheet" href="css/flor-v9.css"></head><body><?php require 'header.php';?><main class="page-shell"><div class="page-intro"><span class="eyebrow">ВАШ ВИБІР</span><h1>Мій <em>кошик</em></h1><p>Ще трішечки — і квіти стануть частиною твоєї історії.</p></div>
 <?php if(!$items):?><div class="empty-state">Тут поки порожньо ♡<br><a href="shop.php" class="btn" style="margin-top:22px">Переглянути квіти ↗</a></div><?php else:?>
 <div class="cart-layout"><div class="cart-items"><?php foreach($items as $r):$custom=bouquet_data($r['custom_data']);?><article class="cart-row"><img src="<?=e(photo($r['image'], $r['product_type'] ?? ''))?>" alt="" onerror="this.onerror=null;this.src='assets/flower-placeholder.svg'"><div class="cart-row-body"><span class="eyebrow"><?=empty($custom)?'З КАТАЛОГУ':'СТВОРЕНО ВАМИ'?></span><h3><?=e($r['name'])?></h3><?php if($custom):?><p><?php foreach(($custom['items']??[]) as $f)echo e($f['name']??'Квітка').' × '.(int)($f['quantity']??0).' · ';?></p><p>Форма: <?=e(['round'=>'класична','airy'=>'повітряна','cascade'=>'каскадна'][$custom['shape']??'round']??'класична')?> · Пакування: <?=e(['cream'=>'молочне','blush'=>'пудрове','kraft'=>'крафт'][$custom['wrap']??'cream']??'молочне')?></p><?php if(!empty($custom['note'])):?><p>Побажання: <?=e($custom['note'])?></p><?php endif;endif;?><strong><?=money($r['price'])?> / шт.</strong></div><div class="cart-row-actions"><form method="post" class="qty-inline"><?=csrf_input()?><input type="hidden" name="action" value="update"><input type="hidden" name="cart_id" value="<?=(int)$r['id']?>"><input type="number" name="quantity" aria-label="Кількість" value="<?=(int)$r['quantity']?>" min="1" max="50"><button type="submit" class="plain-action">Оновити</button></form><form method="post"><?=csrf_input()?><input type="hidden" name="action" value="remove"><input type="hidden" name="cart_id" value="<?=(int)$r['id']?>"><button class="remove-action" data-confirm="Видалити товар із кошика?">Видалити ×</button></form><b><?=money($r['price']*$r['quantity'])?></b></div></article><?php endforeach;?></div><aside class="checkout-summary"><span class="eyebrow">ВАШЕ ЗАМОВЛЕННЯ</span><h3>Усе готово?</h3><div class="summary-total-line"><span>Товари</span><b><?=money($sum)?></b></div><div class="summary-total-line total"><span>Разом</span><strong><?=money($sum)?></strong></div><a href="checkout.php" class="btn btn-wide">Перейти до оформлення ↗</a><a href="builder.php" class="link-underline">Або додати свій букет ↗</a><form method="post" class="clear-cart"><?=csrf_input()?><input type="hidden" name="action" value="clear"><button type="submit" data-confirm="Очистити весь кошик?">Очистити кошик</button></form></aside></div><?php endif;?></main><?php require 'footer.php';?></body></html>
